package vendor

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

func TestReadProvenance_MissingFile(t *testing.T) {
	destDir := t.TempDir()
	p, err := ReadProvenance(destDir)
	if err != nil {
		t.Fatalf("ReadProvenance() unexpected error: %v", err)
	}
	if p != nil {
		t.Errorf("ReadProvenance() = %v, want nil", p)
	}
}

func TestWriteAndReadProvenance_RoundTrip(t *testing.T) {
	destDir := t.TempDir()
	now := time.Now().UTC().Truncate(time.Second)
	want := Provenance{
		Vendor:   "test-vendor",
		Repo:     "https://github.com/example/repo.git",
		Subdir:   "skills/test",
		Ref:      "main",
		Commit:   "0123456789abcdef0123456789abcdef01234567",
		SyncedAt: now,
	}

	if err := WriteProvenance(destDir, want); err != nil {
		t.Fatalf("WriteProvenance() failed: %v", err)
	}

	// Verify header in file
	content, err := os.ReadFile(filepath.Join(destDir, ProvenanceFileName))
	if err != nil {
		t.Fatal(err)
	}
	if !strings.HasPrefix(string(content), "# Generated by axon vendor.") {
		t.Errorf("expected header comment, got: %s", string(content))
	}

	got, err := ReadProvenance(destDir)
	if err != nil {
		t.Fatalf("ReadProvenance() failed: %v", err)
	}
	if got == nil {
		t.Fatal("ReadProvenance() returned nil")
	}

	if got.Vendor != want.Vendor || got.Repo != want.Repo || got.Subdir != want.Subdir ||
		got.Ref != want.Ref || got.Commit != want.Commit || !got.SyncedAt.Equal(want.SyncedAt) {
		t.Errorf("ReadProvenance() = %+v, want %+v", *got, want)
	}
}

func TestReadProvenance_InvalidYAML(t *testing.T) {
	destDir := t.TempDir()
	path := ProvenancePath(destDir)
	if err := os.WriteFile(path, []byte("vendor: [invalid yaml"), 0o644); err != nil {
		t.Fatal(err)
	}

	_, err := ReadProvenance(destDir)
	if err == nil {
		t.Errorf("expected error for invalid YAML, got nil")
	}
}
